<script>document.addEventListener('DOMContentLoaded',()=>{const clock=document.getElementById('live-clock');const tick=()=>{if(clock)clock.textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});};tick();setInterval(tick,1000);const toggle=document.getElementById('navToggle'),side=document.getElementById('mobileSidebar'),backdrop=document.getElementById('mobileNavBackdrop');const close=()=>{side?.classList.add('-translate-x-full');backdrop?.classList.add('hidden');};toggle?.addEventListener('click',()=>{side?.classList.remove('-translate-x-full');backdrop?.classList.remove('hidden');});backdrop?.addEventListener('click',close);});</script>
